#!/usr/bin/env node
// Writes the root ES module (index.mjs and index.d.ts) from the npm package's build in
// js/dist/esm, so the repository itself installs and loads as a package:
//
//   npm i github:Mattbusel/llm-prices#v1
//   import { lookup } from 'https://cdn.jsdelivr.net/gh/Mattbusel/llm-prices@v1/index.mjs';
//   import { lookup } from 'https://esm.sh/gh/Mattbusel/llm-prices@v1';
//
// The price rows live in data.mjs (generated by scripts/build.mjs from prices.json, like every
// other data file), so a price refresh never needs this script. Run it after changing
// js/src/index.ts:
//
//   (cd js && npm run build) && node scripts/rootjs.mjs           rewrite index.mjs, index.d.ts
//   (cd js && npm run build) && node scripts/rootjs.mjs --check   exit 1 when they are stale (CI)

import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const dist = join(root, 'js', 'dist', 'esm');
const HEADER = '// @generated by scripts/rootjs.mjs from js/src/index.ts. Do not edit by hand.\n';

function rewrite(file) {
  const path = join(dist, file);
  if (!existsSync(path)) throw new Error(`${path} is missing: run "npm run build" in js/ first`);
  const text = readFileSync(path, 'utf8').replace(/\r\n/g, '\n');
  const out = text.replace(/from '\.\/data\.js'/g, "from './data.mjs'");
  if (out === text) throw new Error(`${file} does not import './data.js'; update scripts/rootjs.mjs`);
  return HEADER + out;
}

const files = { 'index.mjs': rewrite('index.js'), 'index.d.ts': rewrite('index.d.ts') };

if (process.argv.includes('--check')) {
  const stale = Object.entries(files).filter(([p, c]) => !existsSync(join(root, p)) || readFileSync(join(root, p), 'utf8') !== c);
  if (stale.length) {
    console.error(`out of date with js/src/index.ts (run npm run build in js/, then node scripts/rootjs.mjs):\n${stale.map(([p]) => `  ${p}`).join('\n')}`);
    process.exit(1);
  }
  console.log('index.mjs and index.d.ts match js/src/index.ts');
} else {
  for (const [p, c] of Object.entries(files)) writeFileSync(join(root, p), c);
  console.log(`wrote ${Object.keys(files).join(', ')}`);
}
